1	package com.loja.checkout;
2	
3	import com.loja.checkout.api.ItemRequest;
4	import com.loja.checkout.api.ResumoRequest;
5	import com.loja.checkout.api.ResumoResponse;
6	import com.loja.checkout.clube.NivelClube;
7	import com.loja.checkout.comum.Carrinho;
8	import com.loja.checkout.comum.Catalogo;
9	import com.loja.checkout.comum.Dinheiro;
10	import com.loja.checkout.comum.Item;
11	import com.loja.checkout.comum.Regiao;
12	import com.loja.checkout.comum.ResumoException;
13	import com.loja.checkout.cupom.ContextoCupom;
14	import com.loja.checkout.cupom.Cupom;
15	import com.loja.checkout.cupom.SemCupom;
16	import com.loja.checkout.entrega.ModalidadeEntrega;
17	import com.loja.checkout.pagamento.FormaPagamento;
18	import com.loja.checkout.pagamento.Pagamento;
19	import java.math.BigDecimal;
20	import java.util.List;
21	import java.util.Objects;
22	import java.util.Optional;
23	import org.springframework.stereotype.Service;
24	
25	/** Calcula o resumo da compra, validando na ordem dos códigos de erro. */
26	@Service
27	public class ResumoService {
28	
29	    private final Catalogo<ModalidadeEntrega> modalidades;
30	    private final Catalogo<Cupom> cupons;
31	    private final Catalogo<NivelClube> niveis;
32	    private final Catalogo<FormaPagamento> formasPagamento;
33	
34	    public ResumoService(List<ModalidadeEntrega> modalidades, List<Cupom> cupons,
35	            List<NivelClube> niveis, List<FormaPagamento> formasPagamento) {
36	        this.modalidades = new Catalogo<>(modalidades);
37	        this.cupons = new Catalogo<>(cupons);
38	        this.niveis = new Catalogo<>(niveis);
39	        this.formasPagamento = new Catalogo<>(formasPagamento);
40	    }
41	
42	    public ResumoResponse calcular(ResumoRequest request) {
43	        Carrinho carrinho = carrinho(request.itens());
44	        NivelClube nivel = niveis.buscar(request.nivelClube()).orElseThrow(() -> erro("NIVEL_CLUBE_INVALIDO"));
45	        Regiao regiao = Regiao.buscar(request.regiao()).orElseThrow(() -> erro("REGIAO_INVALIDA"));
46	
47	        ModalidadeEntrega modalidade = modalidades.buscar(request.modalidadeEntrega())
48	                .orElseThrow(() -> erro("MODALIDADE_INVALIDA"));
49	        exigir(modalidade.atende(carrinho), "MODALIDADE_INDISPONIVEL");
50	
51	        BigDecimal subtotal = carrinho.subtotal();
52	        BigDecimal frete = nivel.isentaFrete() ? Dinheiro.ZERO : modalidade.frete(carrinho);
53	
54	        Cupom cupom = cupom(request.cupom());
55	        ContextoCupom contextoCupom = new ContextoCupom(carrinho, frete);
56	        exigir(cupom.aplicavel(contextoCupom), "CUPOM_NAO_APLICAVEL");
57	        BigDecimal desconto = cupom.desconto(contextoCupom);
58	
59	        BigDecimal seguro = regiao.seguro(subtotal);
60	        BigDecimal totalPedido = subtotal.subtract(desconto).add(frete).add(seguro);
61	
62	        FormaPagamento forma = formasPagamento.buscar(request.formaPagamento())
63	                .orElseThrow(() -> erro("FORMA_PAGAMENTO_INVALIDA"));
64	        int parcelas = Objects.requireNonNullElse(request.parcelas(), 1);
65	        exigir(forma.parcelasPermitidas(parcelas), "PARCELAMENTO_INVALIDO");
66	        exigir(forma.disponivel(totalPedido), "FORMA_PAGAMENTO_INDISPONIVEL");
67	        Pagamento pagamento = forma.pagar(totalPedido, parcelas);
68	
69	        return new ResumoResponse(
70	                subtotal,
71	                desconto,
72	                frete,
73	                modalidade.prazoDias(),
74	                seguro,
75	                pagamento.totalFinal().subtract(totalPedido),
76	                pagamento.totalFinal(),
77	                pagamento.parcelas(),
78	                pagamento.valorParcela(),
79	                Dinheiro.percentual(subtotal, nivel.percentualCredito()),
80	                nivel.daBrinde(subtotal));
81	    }
82	
83	    private static Carrinho carrinho(List<ItemRequest> itens) {
84	        exigir(itens != null && !itens.isEmpty() && itens.stream().allMatch(ResumoService::itemValido),
85	                "PEDIDO_INVALIDO");
86	        return new Carrinho(itens.stream()
87	                .map(i -> new Item(i.nome(), i.precoUnitario(), i.quantidade(), i.pesoKg()))
88	                .toList());
89	    }
90	
91	    private static boolean itemValido(ItemRequest item) {
92	        return item != null
93	                && positivo(item.precoUnitario())
94	                && item.quantidade() != null && item.quantidade() > 0
95	                && positivo(item.pesoKg());
96	    }
97	
98	    private static boolean positivo(BigDecimal valor) {
99	        return valor != null && valor.signum() > 0;
100	    }
101	
102	    /** Sem código, o cliente não usou cupom; com código, ele precisa existir. */
103	    private Cupom cupom(String codigo) {
104	        return Optional.ofNullable(codigo)
105	                .map(c -> cupons.buscar(c).orElseThrow(() -> erro("CUPOM_INVALIDO")))
106	                .orElse(SemCupom.INSTANCIA);
107	    }
108	
109	    private static void exigir(boolean condicao, String codigoErro) {
110	        if (!condicao) {
111	            throw erro(codigoErro);
112	        }
113	    }
114	
115	    private static ResumoException erro(String codigo) {
116	        return new ResumoException(codigo);
117	    }
118	}
