3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	
6	/** Arredondamento de valores em dinheiro: centavos, "meio para o par". */
7	public final class Dinheiro {
8	
9	    public static final BigDecimal ZERO = centavos(BigDecimal.ZERO);
10	
11	    private static final BigDecimal CEM = BigDecimal.valueOf(100);
12	
13	    private Dinheiro() {
14	    }
15	
16	    public static BigDecimal centavos(BigDecimal valor) {
17	        return valor.setScale(2, RoundingMode.HALF_EVEN);
18	    }
19	
20	    /** Aplica um percentual (ex.: 2.5 para 2,5%) e arredonda para centavos. */
21	    public static BigDecimal percentual(BigDecimal valor, BigDecimal percentual) {
22	        return centavos(valor.multiply(percentual).divide(CEM));
23	    }
24	}
