8	
9	/** Mapa código → implementação, montado a partir das implementações registradas. */
10	public final class Catalogo<T extends Codificado> {
11	
12	    private final Map<String, T> porCodigo;
13	
14	    public Catalogo(List<T> opcoes) {
15	        this.porCodigo = opcoes.stream().collect(Collectors.toUnmodifiableMap(Codificado::codigo, Function.identity()));
16	    }
17	
18	    public Optional<T> buscar(String codigo) {
19	        return Optional.ofNullable(codigo).map(porCodigo::get);
20	    }
21	}
