1	package com.loja.checkout.pagamento;
2	
3	import com.loja.checkout.comum.Dinheiro;
4	import java.math.BigDecimal;
5	import java.math.MathContext;
6	import org.springframework.stereotype.Component;
7	
8	@Component
9	class Cartao implements FormaPagamento {
10	
11	    private static final int MAXIMO_PARCELAS = 12;
12	    private static final int MAXIMO_SEM_JUROS = 3;
13	    private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
14	
15	    @Override
16	    public String codigo() {
17	        return "CARTAO";
18	    }
19	
20	    @Override
21	    public boolean parcelasPermitidas(int parcelas) {
22	        return parcelas >= 1 && parcelas <= MAXIMO_PARCELAS;
23	    }
24	
25	    @Override
26	    public boolean disponivel(BigDecimal totalPedido) {
27	        return true;
28	    }
29	
30	    @Override
31	    public Pagamento pagar(BigDecimal totalPedido, int parcelas) {
32	        BigDecimal n = BigDecimal.valueOf(parcelas);
33	        if (parcelas <= MAXIMO_SEM_JUROS) {
34	            return new Pagamento(totalPedido, parcelas, Dinheiro.centavos(totalPedido.divide(n, MathContext.DECIMAL128)));
35	        }
36	        BigDecimal parcela = Dinheiro.centavos(parcelaPrice(totalPedido, parcelas));
37	        return new Pagamento(Dinheiro.centavos(parcela.multiply(n)), parcelas, parcela);
38	    }
39	
40	    /** Tabela Price: total × taxa ÷ (1 − (1 + taxa)^−n). */
41	    private static BigDecimal parcelaPrice(BigDecimal total, int parcelas) {
42	        BigDecimal fator = BigDecimal.ONE.add(TAXA_MENSAL).pow(-parcelas, MathContext.DECIMAL128);
43	        return total.multiply(TAXA_MENSAL).divide(BigDecimal.ONE.subtract(fator), MathContext.DECIMAL128);
44	    }
45	}
